function Kt_T2=Kt_T2(e,E,d,L)
%pretvotba stolpiènega vektorja e v komponente
ea1=e(1,1); ea2=e(2,1); ea3=e(3,1); ea4=e(4,1); ea5=e(5,1); ea6=e(6,1);
ea7=e(7,1); ea8=e(8,1); ea9=e(9,1); ea10=e(10,1); ea11=e(11,1); ea12=e(12,1);


I=(pi*d^4*1e-12)/64;  %1e-12 pride iz pretvorbe mm v m

 f_crt =(ea10*((2*ea10)/15 - ea4/30 + ea1/(10*L) - ea7/(10*L)) - ea4*(ea10/30 - (2*ea4)/15 - ea1/(10*L) + ea7/(10*L)) + ea11*((2*ea11)/15 - ea5/30 + ea2/(10*L) - ea8/(10*L)) + ea12*((2*ea12)/15 - ea6/30 + ea3/(10*L) - ea9/(10*L)) - ea5*(ea11/30 - (2*ea5)/15 - ea2/(10*L) + ea8/(10*L)) - ea6*(ea12/30 - (2*ea6)/15 - ea3/(10*L) + ea9/(10*L)) + ea1*((6*ea1)/(5*L^2) + ea10/(10*L) + ea4/(10*L) - (6*ea7)/(5*L^2)) + ea2*(ea11/(10*L) + (6*ea2)/(5*L^2) + ea5/(10*L) - (6*ea8)/(5*L^2)) - ea7*((6*ea1)/(5*L^2) + ea10/(10*L) + ea4/(10*L) - (6*ea7)/(5*L^2)) + ea3*(ea12/(10*L) + (6*ea3)/(5*L^2) + ea6/(10*L) - (6*ea9)/(5*L^2)) - ea8*(ea11/(10*L) + (6*ea2)/(5*L^2) + ea5/(10*L) - (6*ea8)/(5*L^2)) - ea9*(ea12/(10*L) + (6*ea3)/(5*L^2) + ea6/(10*L) - (6*ea9)/(5*L^2)))^(1/2);
 
 kapa_crt =(ea1*((12*ea1)/L^4 + (6*ea10)/L^3 + (6*ea4)/L^3 - (12*ea7)/L^4) + ea10*((6*ea1)/L^3 + (4*ea10)/L^2 + (2*ea4)/L^2 - (6*ea7)/L^3) + ea4*((6*ea1)/L^3 + (2*ea10)/L^2 + (4*ea4)/L^2 - (6*ea7)/L^3) + ea11*((4*ea11)/L^2 + (6*ea2)/L^3 + (2*ea5)/L^2 - (6*ea8)/L^3) + ea2*((6*ea11)/L^3 + (12*ea2)/L^4 + (6*ea5)/L^3 - (12*ea8)/L^4) - ea7*((12*ea1)/L^4 + (6*ea10)/L^3 + (6*ea4)/L^3 - (12*ea7)/L^4) + ea12*((4*ea12)/L^2 + (6*ea3)/L^3 + (2*ea6)/L^2 - (6*ea9)/L^3) + ea5*((2*ea11)/L^2 + (6*ea2)/L^3 + (4*ea5)/L^2 - (6*ea8)/L^3) + ea3*((6*ea12)/L^3 + (12*ea3)/L^4 + (6*ea6)/L^3 - (12*ea9)/L^4) - ea8*((6*ea11)/L^3 + (12*ea2)/L^4 + (6*ea5)/L^3 - (12*ea8)/L^4) + ea6*((2*ea12)/L^2 + (6*ea3)/L^3 + (4*ea6)/L^2 - (6*ea9)/L^3) - ea9*((6*ea12)/L^3 + (12*ea3)/L^4 + (6*ea6)/L^3 - (12*ea9)/L^4))^(1/2)/(ea10*((2*ea10)/15 - ea4/30 + ea1/(10*L) - ea7/(10*L)) - ea4*(ea10/30 - (2*ea4)/15 - ea1/(10*L) + ea7/(10*L)) + ea11*((2*ea11)/15 - ea5/30 + ea2/(10*L) - ea8/(10*L)) + ea12*((2*ea12)/15 - ea6/30 + ea3/(10*L) - ea9/(10*L)) - ea5*(ea11/30 - (2*ea5)/15 - ea2/(10*L) + ea8/(10*L)) - ea6*(ea12/30 - (2*ea6)/15 - ea3/(10*L) + ea9/(10*L)) + ea1*((6*ea1)/(5*L^2) + ea10/(10*L) + ea4/(10*L) - (6*ea7)/(5*L^2)) + ea2*(ea11/(10*L) + (6*ea2)/(5*L^2) + ea5/(10*L) - (6*ea8)/(5*L^2)) - ea7*((6*ea1)/(5*L^2) + ea10/(10*L) + ea4/(10*L) - (6*ea7)/(5*L^2)) + ea3*(ea12/(10*L) + (6*ea3)/(5*L^2) + ea6/(10*L) - (6*ea9)/(5*L^2)) - ea8*(ea11/(10*L) + (6*ea2)/(5*L^2) + ea5/(10*L) - (6*ea8)/(5*L^2)) - ea9*(ea12/(10*L) + (6*ea3)/(5*L^2) + ea6/(10*L) - (6*ea9)/(5*L^2)));

Kt_T2=E*I*L*((I1(L)/f_crt^4)-2*(kapa_crt^2/f_crt^2)*I2(L))*e; 


   function I1=I1(L)
I1 =... 
[  12/L^4,       0,       0,  6/L^3,      0,      0, -12/L^4,       0,       0,  6/L^3,      0,      0;
       0,  12/L^4,       0,      0,  6/L^3,      0,       0, -12/L^4,       0,      0,  6/L^3,      0;
       0,       0,  12/L^4,      0,      0,  6/L^3,       0,       0, -12/L^4,      0,      0,  6/L^3;
   6/L^3,       0,       0,  4/L^2,      0,      0,  -6/L^3,       0,       0,  2/L^2,      0,      0;
       0,   6/L^3,       0,      0,  4/L^2,      0,       0,  -6/L^3,       0,      0,  2/L^2,      0;
       0,       0,   6/L^3,      0,      0,  4/L^2,       0,       0,  -6/L^3,      0,      0,  2/L^2;
 -12/L^4,       0,       0, -6/L^3,      0,      0,  12/L^4,       0,       0, -6/L^3,      0,      0;
       0, -12/L^4,       0,      0, -6/L^3,      0,       0,  12/L^4,       0,      0, -6/L^3,      0;
       0,       0, -12/L^4,      0,      0, -6/L^3,       0,       0,  12/L^4,      0,      0, -6/L^3;
   6/L^3,       0,       0,  2/L^2,      0,      0,  -6/L^3,       0,       0,  4/L^2,      0,      0;
       0,   6/L^3,       0,      0,  2/L^2,      0,       0,  -6/L^3,       0,      0,  4/L^2,      0;
       0,       0,   6/L^3,      0,      0,  2/L^2,       0,       0,  -6/L^3,      0,      0,  4/L^2];
end

    function I2=I2(L)
 I2=...
 [ 6/(5*L^2),          0,          0,  1/(10*L),         0,         0, -6/(5*L^2),          0,          0,  1/(10*L),         0,         0;
          0,  6/(5*L^2),          0,         0,  1/(10*L),         0,          0, -6/(5*L^2),          0,         0,  1/(10*L),         0;
          0,          0,  6/(5*L^2),         0,         0,  1/(10*L),          0,          0, -6/(5*L^2),         0,         0,  1/(10*L);
   1/(10*L),          0,          0,      2/15,         0,         0,  -1/(10*L),          0,          0,     -1/30,         0,         0;
          0,   1/(10*L),          0,         0,      2/15,         0,          0,  -1/(10*L),          0,         0,     -1/30,         0;
          0,          0,   1/(10*L),         0,         0,      2/15,          0,          0,  -1/(10*L),         0,         0,     -1/30;
 -6/(5*L^2),          0,          0, -1/(10*L),         0,         0,  6/(5*L^2),          0,          0, -1/(10*L),         0,         0;
          0, -6/(5*L^2),          0,         0, -1/(10*L),         0,          0,  6/(5*L^2),          0,         0, -1/(10*L),         0;
          0,          0, -6/(5*L^2),         0,         0, -1/(10*L),          0,          0,  6/(5*L^2),         0,         0, -1/(10*L);
   1/(10*L),          0,          0,     -1/30,         0,         0,  -1/(10*L),          0,          0,      2/15,         0,         0;
          0,   1/(10*L),          0,         0,     -1/30,         0,          0,  -1/(10*L),          0,         0,      2/15,         0;
          0,          0,   1/(10*L),         0,         0,     -1/30,          0,          0,  -1/(10*L),         0,         0,      2/15];
    end
 
end


 